    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Rol {\n  ESTUDIANTE\n  EMPRESA\n  COORDINADOR\n  DOCENTE\n}\n\nmodel Coordinador {\n  id        String  @id @default(uuid())\n  usuarioId String  @unique\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n  cargo     String?\n\n  procesosAsignados ProcesoGrado[]\n}\n\nenum Modalidad {\n  INVESTIGACION\n  DIPLOMADO\n  PRACTICA\n}\n\nenum TipoDocente {\n  DOCENTE\n  EGRESADO\n}\n\nenum TipoPractica {\n  UNIVERSIDAD\n  INDEPENDIENTE\n}\n\nmodel Usuario {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  nombre    String\n  rol       Rol\n  createdAt DateTime @default(now())\n\n  estudiante  Estudiante?\n  empresa     Empresa?\n  docente     Docente?\n  coordinador Coordinador?\n}\n\nmodel Estudiante {\n  id        String  @id @default(uuid())\n  usuarioId String  @unique\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n  codigo    String  @unique\n  programa  String\n  semestre  Int\n\n  procesoGrado  ProcesoGrado?\n  postulaciones Postulacion[]\n}\n\nmodel Empresa {\n  id            String  @id @default(uuid())\n  usuarioId     String  @unique\n  usuario       Usuario @relation(fields: [usuarioId], references: [id])\n  nombreEmpresa String\n  nit           String  @unique\n  sector        String\n\n  ofertas Oferta[]\n}\n\nmodel Docente {\n  id           String      @id @default(uuid())\n  usuarioId    String      @unique\n  usuario      Usuario     @relation(fields: [usuarioId], references: [id])\n  tipo         TipoDocente\n  especialidad String\n\n  procesosAsesorados ProcesoGrado[]\n}\n\nmodel ProcesoGrado {\n  id              String       @id @default(uuid())\n  estudianteId    String       @unique\n  estudiante      Estudiante   @relation(fields: [estudianteId], references: [id])\n  modalidad       Modalidad\n  estado          String       @default(\"EN_PROCESO\")\n  asesorId        String?\n  asesor          Docente?     @relation(fields: [asesorId], references: [id])\n  coordinadorId   String?\n  coordinador     Coordinador? @relation(fields: [coordinadorId], references: [id])\n  fechaAsignacion DateTime?\n  fechaInicio     DateTime     @default(now())\n\n  investigacion Investigacion?\n  diplomado     Diplomado?\n  practica      Practica?\n}\n\nmodel Investigacion {\n  id                 String       @id @default(uuid())\n  procesoGradoId     String       @unique\n  procesoGrado       ProcesoGrado @relation(fields: [procesoGradoId], references: [id])\n  grupoInvestigacion String\n  ideaPropuesta      String\n  materiaMatriculada Boolean      @default(false)\n}\n\nmodel Diplomado {\n  id               String       @id @default(uuid())\n  procesoGradoId   String       @unique\n  procesoGrado     ProcesoGrado @relation(fields: [procesoGradoId], references: [id])\n  nombreCurso      String\n  institucion      String\n  estadoAprobacion String       @default(\"PENDIENTE\")\n}\n\nmodel Practica {\n  id               String       @id @default(uuid())\n  procesoGradoId   String       @unique\n  procesoGrado     ProcesoGrado @relation(fields: [procesoGradoId], references: [id])\n  tipo             TipoPractica\n  horasCompletadas Int          @default(0)\n  ofertaId         String?\n  oferta           Oferta?      @relation(fields: [ofertaId], references: [id])\n  estadoReporte    String       @default(\"PENDIENTE\")\n}\n\nmodel Oferta {\n  id               String   @id @default(uuid())\n  empresaId        String\n  empresa          Empresa  @relation(fields: [empresaId], references: [id])\n  titulo           String\n  descripcion      String\n  perfilBuscado    String\n  estado           String   @default(\"ABIERTA\")\n  fechaPublicacion DateTime @default(now())\n\n  postulaciones Postulacion[]\n  practicas     Practica[]\n}\n\nmodel Postulacion {\n  id           String     @id @default(uuid())\n  ofertaId     String\n  oferta       Oferta     @relation(fields: [ofertaId], references: [id])\n  estudianteId String\n  estudiante   Estudiante @relation(fields: [estudianteId], references: [id])\n  estado       String     @default(\"PENDIENTE\")\n  fecha        DateTime   @default(now())\n}\n",
